// Build Telegram message for each matched job
const job = $json;

const strengths = Array.isArray(job.strengths) 
  ? job.strengths.slice(0, 3).join('\n  • ')
  : (job.strengths || 'See full analysis');

const missing = Array.isArray(job.missing_skills) && job.missing_skills.length > 0
  ? job.missing_skills.slice(0, 3).join(', ')
  : 'None identified';

const scoreBar = (score) => {
  const filled = Math.round(score / 10);
  return '█'.repeat(filled) + '░'.repeat(10 - filled) + ` ${score}%`;
};

const remoteTag = job.remote ? '🌍 Remote' : `📍 ${job.location || 'See listing'}`;
const salaryTag = job.salary ? `\n💰 Salary: ${job.salary}` : '';
const tier = job.match_score >= 90 ? '🔥 EXCELLENT MATCH' 
           : job.match_score >= 80 ? '⭐ STRONG MATCH'
           : '✅ GOOD MATCH';

const message = `${tier}

🏢 *${job.company}*
💼 ${job.title}
${remoteTag}${salaryTag}

📊 Match Scores:
  Overall:   ${scoreBar(Math.round(job.match_score))}
  Technical: ${scoreBar(Math.round(job.technical_score))}
  Experience:${scoreBar(Math.round(job.experience_score))}

✅ *Strengths:*
  • ${strengths}

⚠️ *Gaps:* ${missing}

🔗 ${job.url}`;

return [{
  json: {
    job_id: job.job_id,
    message: message,
    company: job.company,
    title: job.title,
    url: job.url,
    match_score: job.match_score,
    application_id: job.application_id
  }
}];
